#!/usr/bin/env python3
"""
Changelog Generator & Version Manager for monorepo.
Generates changelogs and updates version numbers based on Git history.
"""

import os
import re
import subprocess
from collections import defaultdict
from datetime import datetime


def run_cmd(args):
    """Run a shell command and return stdout."""
    result = subprocess.run(args, capture_output=True, text=True, cwd=os.getcwd())
    return result.stdout.strip()


def get_last_tag():
    """Get the most recent git tag."""
    try:
        tag = run_cmd(['git', 'describe', '--tags', '--abbrev=0'])
        return tag
    except Exception:
        return None


def get_commits_since_tag(tag):
    """Get commit info from tag to HEAD using pipe-separated format."""
    if tag is None:
        tag = 'HEAD'
    # Format: hash|subject|body
    output = run_cmd(['git', 'log', f'{tag}..HEAD', '--format=%H|%s|%b'])
    commits = []
    for line in output.split('\n'):
        if not line:
            continue
        parts = line.split('|', 2)  # Split into max 3 parts
        if len(parts) >= 2:
            commits.append({
                'hash': parts[0],
                'subject': parts[1],
                'body': parts[2] if len(parts) > 2 else ''
            })
        elif len(parts) == 1:
            commits.append({
                'hash': parts[0],
                'subject': '',
                'body': ''
            })
    return commits


def parse_commit_type_from_subject(subject):
    """
    Parse commit subject in format: type(scope): description
    Returns (type, scope, description) or None if invalid.
    """
    pattern = r'^(feat|fix)\(([a-zA-Z0-9_-]+)\):\s*(.*)$'
    match = re.match(pattern, subject.strip())
    if match:
        return match.group(1), match.group(2), match.group(3)
    return None


def get_files_changed_in_commit(commit_hash):
    """Get list of files changed in a commit."""
    output = run_cmd(['git', 'show', '--name-only', '--format=', commit_hash])
    files = [f for f in output.split('\n') if f]
    return files


def get_packages_affected_by_commit(commit_hash, packages_dir='packages'):
    """
    Determine which packages are affected by a commit.
    Returns set of package names.
    """
    files = get_files_changed_in_commit(commit_hash)
    packages = set()
    for f in files:
        if f.startswith(packages_dir + '/'):
            # Extract package name: packages/pkg-name/...
            parts = f.split('/')
            if len(parts) >= 2:
                pkg_name = parts[1]
                packages.add(pkg_name)
    return packages


def determine_bump_level(commit_type, has_breaking_change):
    """
    Determine version bump level from commit type.
    MAJOR: breaking change
    MINOR: feat
    PATCH: fix
    """
    if has_breaking_change:
        return 'MAJOR'
    elif commit_type == 'feat':
        return 'MINOR'
    elif commit_type == 'fix':
        return 'PATCH'
    return None


def bump_version(current, level):
    """Bump semantic version according to level."""
    parts = current.split('.')
    if len(parts) != 3:
        return current
    major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])

    if level == 'MAJOR':
        major += 1
        minor, patch = 0, 0
    elif level == 'MINOR':
        minor += 1
        patch = 0
    elif level == 'PATCH':
        patch += 1

    return f"{major}.{minor}.{patch}"


def get_package_deps(packages_dir='packages'):
    """
    Load dependency graph.
    Returns: dict of {package_name: [list of packages it depends on]}
    """
    deps = {}
    if not os.path.exists(packages_dir):
        return deps

    for item in os.listdir(packages_dir):
        pkg_path = os.path.join(packages_dir, item)
        if os.path.isdir(pkg_path):
            version_file = os.path.join(pkg_path, 'VERSION')
            if os.path.exists(version_file):
                deps_file = os.path.join(pkg_path, 'deps.txt')
                if os.path.exists(deps_file):
                    with open(deps_file, 'r') as f:
                        pkg_deps = [line.strip() for line in f if line.strip() and not line.startswith('#')]
                    deps[item] = pkg_deps
                else:
                    deps[item] = []
    return deps


def build_reverse_deps(deps):
    """
    Build reverse dependency map.
    Given deps = {A: [B, C]} meaning A depends on B, C
    Returns rev_deps = {B: [A], C: [A]} meaning B, C are depended on by A
    """
    rev_deps = defaultdict(list)
    for pkg, pkg_deps in deps.items():
        for dep in pkg_deps:
            rev_deps[dep].append(pkg)
    return dict(rev_deps)


def main():
    packages_dir = 'packages'

    # Get last tag
    last_tag = get_last_tag()
    print(f"Last tag: {last_tag}")

    # Get commits
    commits = get_commits_since_tag(last_tag)
    print(f"Found {len(commits)} commits")

    if not commits:
        print("No commits to process.")
        return

    # Step 1: Map commits to packages and parse commit messages
    # commit_data[commit_hash] = {pkg1, pkg2, ...}
    commit_to_packages = {}

    for commit in commits:
        hash_val = commit['hash']
        subject = commit['subject']
        body = commit['body']

        # Get packages affected by this commit
        packages = get_packages_affected_by_commit(hash_val)
        if packages:
            commit_to_packages[hash_val] = packages

        # Parse commit message
        parsed = parse_commit_type_from_subject(subject)
        commit_type = parsed[0] if parsed else None
        scope = parsed[1] if parsed else ''
        description = parsed[2] if parsed else subject

        # Check for BREAKING CHANGE in subject or body
        has_breaking = 'BREAKING CHANGE' in subject or 'BREAKING CHANGE' in body

        # Store commit info for later
        commit_info[hash_val] = {
            'subject': subject,
            'body': body,
            'type': commit_type,
            'scope': scope,
            'description': description,
            'has_breaking': has_breaking
        }

    # Step 2: Compute direct version bumps per package
    # package_direct_bumps[pkg] = {level: 'MAJOR'/'MINOR'/'PATCH', descriptions: [...]}
    package_direct_bumps = defaultdict(lambda: {'level': None, 'descriptions': []})

    for hash_val, packages in commit_to_packages.items():
        info = commit_info[hash_val]
        for pkg in packages:
            bump_level = determine_bump_level(info['type'], info['has_breaking'])
            if bump_level:
                # Keep highest level found for this package from direct commits
                current_level = package_direct_bumps[pkg]['level']
                # MAJOR > MINOR > PATCH
                level_order = {'MAJOR': 3, 'MINOR': 2, 'PATCH': 1}
                if level_order.get(bump_level, 0) > level_order.get(current_level, 0):
                    package_direct_bumps[pkg]['level'] = bump_level
                # Collect descriptions (all of them)
                package_direct_bumps[pkg]['descriptions'].append({
                    'type': info['type'],
                    'description': info['description']
                })

    print(f"Direct bumps: {dict(package_direct_bumps)}")

    # Step 3: Build dependency graph and propagate
    direct_deps = get_package_deps(packages_dir)
    reverse_deps = build_reverse_deps(direct_deps)
    print(f"Direct deps: {direct_deps}")
    print(f"Reverse deps: {reverse_deps}")

    # package_final_bumps[pkg] = {'level': ..., 'direct': bool, 'descriptions': [...]}
    package_final = {}
    for pkg, data in package_direct_bumps.items():
        package_final[pkg] = {
            'level': data['level'],
            'direct': True,
            'descriptions': data['descriptions']
        }

    # Propagate dependency bumps
    # A package bumped directly causes PATCH bumps in packages that depend on it
    # We need to iterate until propagation stabilizes

    changed = True
    while changed:
        changed = False
        for pkg, dependents in reverse_deps.items():
            # If pkg has any bump (direct or propagated), propagate to dependents
            if package_final.get(pkg, {}).get('level'):
                for dep_pkg in dependents:
                    current = package_final.get(dep_pkg, {})
                    current_level = current.get('level')

                    # If dep_pkg has no level yet, set to PATCH
                    if current_level is None:
                        package_final[dep_pkg] = {
                            'level': 'PATCH',
                            'direct': False,
                            'descriptions': [{'type': 'deps', 'description': 'update dependencies'}]
                        }
                        changed = True
                    # If it already has a level, we don't downgrade (PATCH is lowest)
                    # But we might need to track that it was bumped via dependency for changelog

    print(f"Final bumps after propagation: {package_final}")

    # Step 4: Update VERSION files and CHANGELOG.md for each package
    today = datetime.now().strftime('%Y-%m-%d')

    for pkg, data in package_final.items():
        if data['level'] is None:
            continue

        # Read current version
        version_file = os.path.join(packages_dir, pkg, 'VERSION')
        with open(version_file, 'r') as f:
            current_version = f.read().strip()

        # Compute new version
        new_version = bump_version(current_version, data['level'])

        # Write new version
        with open(version_file, 'w') as f:
            f.write(new_version + '\n')

        print(f"Updated {pkg}/VERSION: {current_version} -> {new_version}")

        # Prepare CHANGELOG.md content
        # Features and Bug Fixes from direct commits
        features = [d['description'] for d in data['descriptions'] if d['type'] == 'feat']
        fixes = [d['description'] for d in data['descriptions'] if d['type'] == 'fix']

        # Check if this is a dependency-only bump (no direct commits, level is PATCH)
        is_deps_only = not data['direct'] and data['level'] == 'PATCH'

        # Build changelog lines
        lines = [f"## {new_version} ({today})"]

        if features:
            lines.append("### Features")
            for desc in features:
                lines.append(f"- {desc}")

        if fixes:
            lines.append("### Bug Fixes")
            for desc in fixes:
                lines.append(f"- {desc}")

        if is_deps_only:
            lines.append("### Dependencies")
            lines.append("- update dependencies")

        # Write CHANGELOG.md (append new version section)
        changelog_file = os.path.join(packages_dir, pkg, 'CHANGELOG.md')
        if os.path.exists(changelog_file):
            with open(changelog_file, 'r') as f:
                existing = f.read()
            # Check if already has this version
            if f"## {new_version}" not in existing:
                # Prepend new version section
                with open(changelog_file, 'w') as f:
                    f.write('\n'.join(lines) + '\n' + existing)
        else:
            with open(changelog_file, 'w') as f:
                f.write('\n'.join(lines) + '\n')

        print(f"Updated {pkg}/CHANGELOG.md")

        # Collect for release-notes.md
        # Only include direct commits (not dependency-triggered)
        pkg_release_items = []
        if data['direct']:
            for d in data['descriptions']:
                pkg_release_items.append(f"[{d['type']}] {d['description']}")
        if is_deps_only:
            pkg_release_items.append("[deps] update dependencies")

        release_notes[pkg] = pkg_release_items

    # Step 5: Write release-notes.md
    with open('release-notes.md', 'w') as f:
        f.write("# Release Notes\n\n")
        for pkg in sorted(release_notes.keys()):
            f.write(f"## {pkg}\n")
            for item in release_notes[pkg]:
                f.write(f"- {item}\n")
            f.write("\n")

    print("Generated release-notes.md")


if __name__ == '__main__':
    main()
