    for f in files:
        # Skip CHANGELOG.md files (generated by this script)
        if f.endswith('CHANGELOG.md'):
            continue
        if f.startswith(packages_dir + '/'):
            # Extract package name: packages/pkg-name/...
            parts = f.split('/')
            if len(parts) >= 2:
                pkg_name = parts[1]
                packages.add(pkg_name)
    return packages


def determine_bump_level(commit_type, has_breaking_change):
    """
    Determine version bump level from commit type.
    MAJOR: breaking change
    MINOR: feat
    PATCH: fix
    """
    if has_breaking_change:
        return 'MAJOR'
    elif commit_type == 'feat':
        return 'MINOR'
    elif commit_type == 'fix':
        return 'PATCH'
    return None


def bump_version(current, level):
    """Bump semantic version according to level."""
    parts = current.split('.')
    if len(parts) != 3:
        return current
    major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])

    if level == 'MAJOR':
        major += 1
        minor, patch = 0, 0
    elif level == 'MINOR':
        minor += 1
        patch = 0
    elif level == 'PATCH':
        patch += 1

    return f"{major}.{minor}.{patch}"


def get_package_deps(packages_dir='packages'):
    """
    Load dependency graph.
    Returns: dict of {package_name: [list of packages it depends on]}
    """
    deps = {}
    if not os.path.exists(packages_dir):
        return deps

    for item in os.listdir(packages_dir):
        pkg_path = os.path.join(packages_dir, item)
        if os.path.isdir(pkg_path):
            version_file = os.path.join(pkg_path, 'VERSION')
            if os.path.exists(version_file):
                deps_file = os.path.join(pkg_path, 'deps.txt')
                if os.path.exists(deps_file):
                    with open(deps_file, 'r') as f:
                        pkg_deps = [line.strip() for line in f if line.strip() and not line.startswith('#')]
                    deps[item] = pkg_deps
                else:
                    deps[item] = []
    return deps


def build_reverse_deps(deps):
    """
    Build reverse dependency map.
    Given deps = {A: [B, C]} meaning A depends on B, C
    Returns rev_deps = {B: [A], C: [A]} meaning B, C are depended on by A
    """
    rev_deps = defaultdict(list)
    for pkg, pkg_deps in deps.items():
        for dep in pkg_deps:
            rev_deps[dep].append(pkg)
    return dict(rev_deps)


